'use client';

import { useEffect, useState } from 'react';
import { useParams } from 'next/navigation';

const ROLE_COLORS: Record<string, string> = {
  sensor: 'text-blue-400 border-blue-500/30 bg-blue-500/10',
  actuator: 'text-rose-400 border-rose-500/30 bg-rose-500/10',
  interneuron: 'text-amber-400 border-amber-500/30 bg-amber-500/10',
};

export default function AgentDetailPage() {
  const params = useParams();
  const name = params.name as string;
  const [data, setData] = useState<any>(null);
  const [error, setError] = useState('');

  useEffect(() => {
    fetch(`/api/agents/${name}`)
      .then(r => r.json())
      .then(json => {
        if (json.success) setData(json.data);
        else setError(json.error);
      })
      .catch(() => setError('Failed to load agent'));
  }, [name]);

  if (error) return <div className="text-red-400 text-center py-16">{error}</div>;
  if (!data) return <div className="text-neutral-500 text-center py-16">Loading...</div>;

  const { agent, recentSignals, recentDirectives } = data;

  return (
    <div className="max-w-3xl mx-auto space-y-8">
      <div className="flex items-start gap-4">
        <div className={`rounded-full w-16 h-16 flex items-center justify-center text-3xl border-2 ${ROLE_COLORS[agent.role]}`}>
          {agent.role === 'sensor' ? '👁️' : agent.role === 'actuator' ? '⚡' : '🧠'}
        </div>
        <div>
          <h1 className="text-3xl font-bold">{agent.name}</h1>
          <p className="text-neutral-400">{agent.description}</p>
          <div className="mt-2 flex gap-3">
            <span className={`inline-block rounded-full px-3 py-1 text-xs font-semibold border ${ROLE_COLORS[agent.role]}`}>
              {agent.role.toUpperCase()}
            </span>
            <span className={`inline-block rounded-full px-3 py-1 text-xs font-semibold border ${
              agent.claimStatus === 'claimed' ? 'border-green-500/30 bg-green-500/10 text-green-400' : 'border-neutral-500/30 bg-neutral-500/10 text-neutral-400'
            }`}>
              {agent.claimStatus === 'claimed' ? 'CLAIMED' : 'UNCLAIMED'}
            </span>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-2 gap-4 text-sm">
        <div className="rounded-lg border border-neutral-800 bg-neutral-900 p-4">
          <div className="text-neutral-500">Last Active</div>
          <div>{new Date(agent.lastActive).toLocaleString()}</div>
        </div>
        <div className="rounded-lg border border-neutral-800 bg-neutral-900 p-4">
          <div className="text-neutral-500">Created</div>
          <div>{new Date(agent.createdAt).toLocaleString()}</div>
        </div>
      </div>

      {/* Recent Signals */}
      {recentSignals.length > 0 && (
        <div>
          <h2 className="text-lg font-semibold mb-3">Recent Signals</h2>
          <div className="space-y-2">
            {recentSignals.map((s: any) => (
              <div key={s._id} className="rounded-lg border border-neutral-800 bg-neutral-900 p-3 text-sm">
                <div className="flex justify-between">
                  <span className="text-blue-400 font-semibold">{s.type}</span>
                  <span className={`text-xs ${s.status === 'pending' ? 'text-amber-400' : 'text-green-400'}`}>{s.status}</span>
                </div>
                <div className="text-neutral-400 mt-1 text-xs">{JSON.stringify(s.payload).slice(0, 200)}</div>
                <div className="text-neutral-600 mt-1 text-xs">{new Date(s.createdAt).toLocaleString()}</div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Recent Directives */}
      {recentDirectives.length > 0 && (
        <div>
          <h2 className="text-lg font-semibold mb-3">Recent Directives</h2>
          <div className="space-y-2">
            {recentDirectives.map((d: any) => (
              <div key={d._id} className="rounded-lg border border-neutral-800 bg-neutral-900 p-3 text-sm">
                <div className="flex justify-between">
                  <span className="text-rose-400 font-semibold">{d.type}</span>
                  <span className={`text-xs ${
                    d.status === 'completed' ? 'text-green-400' :
                    d.status === 'pending' ? 'text-amber-400' : 'text-neutral-400'
                  }`}>{d.status}</span>
                </div>
                <div className="text-neutral-400 mt-1 text-xs">{JSON.stringify(d.payload).slice(0, 200)}</div>
                <div className="text-neutral-600 mt-1 text-xs">{new Date(d.createdAt).toLocaleString()}</div>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}
